# First, let's understand the XFA structure better by examining the XML
import pikepdf

pdf = pikepdf.open("/root/sc100-blank.pdf")

# Check for XFA
acroform = pdf.Root.get('/AcroForm')
if acroform:
    xfa = acroform.get('/XFA')
    if xfa:
        print("XFA found, type:", type(xfa))
        if isinstance(xfa, pikepdf.Array):
            print("XFA is an array with", len(xfa), "items")
            for i, item in enumerate(xfa):
                if isinstance(item, pikepdf.String):
                    print(f"  [{i}]: String = {str(item)}")
                elif isinstance(item, pikepdf.Stream):
                    print(f"  [{i}]: Stream (length={len(item.read_bytes())})")
                elif isinstance(item, pikepdf.Name):
                    print(f"  [{i}]: Name = {str(item)}")
                else:
                    print(f"  [{i}]: {type(item)} = {item}")
